83	function assignTiers(heroes, scoreKey) {
84	  const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
85	  const n = sorted.length;
86	  const thresholds = getTierThresholds();
87	  sorted.forEach((h, rank) => {
88	    const pct = 1 - rank / n;
89	    let tier = "T4";
90	    for (const t of thresholds) {
91	      if (pct >= t.pct) { tier = t.tier; break; }
92	    }
93	    h.tier = tier;
94	    h.rank = rank + 1;
95	  });
96	}
