98	// ============================================================
99	// LOLM 算法
100	// ============================================================
101	function computeLOLM(rawData) {
102	  const hasLanes = gameConfig.hasLanes;
103	  const lanes = {};
104	  const allHeroes = [];
105	
106	  for (const laneCfg of gameConfig.lanes) {
107	    const raw = rawData[laneCfg.name];
108	    if (!raw) continue;
109	    const heroes = raw.map(h => ({
110	      name: h.heroName,
111	      lane: laneCfg.name,
112	      headIcon: gameConfig.headIconPath ? (gameConfig.gameId + "/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
113	      wr: parsePct(h.winRate),
114	      pr: parsePct(h.pickRate),
115	      br: parsePct(h.banRate),
116	      bp: parsePct(h.pickRate) + parsePct(h.banRate)
117	    }));
118	    lanes[laneCfg.name] = heroes;
119	    allHeroes.push(...heroes);
120	  }
121	
122	  // Z-score 加权（分路内计算 Z-score）
123	  for (const [laneName, heroes] of Object.entries(lanes)) {
124	    const zWr = zScores(heroes.map(h => h.wr));
125	    const zPr = zScores(heroes.map(h => h.pr));
126	    const zBr = zScores(heroes.map(h => h.br));
127	    heroes.forEach((h, i) => {
128	      h.z_wr = zWr[i]; h.z_pr = zPr[i]; h.z_br = zBr[i];
129	      h.raw_zscore = 0.5 * zWr[i] + 1.0 * zPr[i] + 3.0 * zBr[i];
130	    });
131	  }
132	
133	  // 简易公式
134	  for (const [laneName, heroes] of Object.entries(lanes)) {
135	    heroes.forEach(h => {
136	      h.raw_simple = Math.pow(h.wr, 0.3) * (h.pr + 2.5 * h.br) * 100;
137	    });
138	  }
139	
140	  // 分路内 min-max 归一化
141	  function normalize(heroes, rawKey, normKey) {
142	    const vals = heroes.map(h => h[rawKey]);
143	    const lo = Math.min(...vals), hi = Math.max(...vals);
144	    const rng = hi - lo || 1;
145	    heroes.forEach(h => { h[normKey] = ((h[rawKey] - lo) / rng) * 100; });
146	  }
147	
148	  for (const [, heroes] of Object.entries(lanes)) {
149	    normalize(heroes, "raw_zscore", "score_zscore");
150	    normalize(heroes, "raw_simple", "score_simple");
151	  }
152	
153	  // 全局归一化
154	  normalize(allHeroes, "raw_zscore", "score_zscore_global");
155	  normalize(allHeroes, "raw_simple", "score_simple_global");
156	
157	  // 分配梯度
158	  for (const [, heroes] of Object.entries(lanes)) {
159	    assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
160	    assignTiersWithKey(heroes, "score_simple", "tier_simple");
161	    assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
162	  }
163	
164	  function assignTiersWithKey(heroes, scoreKey, tierKey) {
165	    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
166	    const n = sorted.length;
167	    const thresholds = getTierThresholds();
168	    sorted.forEach((h, i) => {
169	      const pct = 1 - i / n;
170	      let tier = "T4";
171	      for (const t of thresholds) {
172	        if (pct >= t.pct) { tier = t.tier; break; }
173	      }
174	      h[tierKey] = tier;
175	      // Store lane rank under a consistent key: _rank_zscore / _rank_simple
176	      if (tierKey === "tier_zscore") h._rank_zscore = i + 1;
177	      if (tierKey === "tier_simple") h._rank_simple = i + 1;
178	    });
179	  }
180	
181	  // 全局排名
182	  const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
183	  globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
184	  const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
185	  globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });
186	
187	  return { lanes, allHeroes, globalZ, globalSimple };
188	}
