190	// ============================================================
191	// 曙光英雄算法（从 Python validate_pure.py 移植）
192	// ============================================================
193	function computeSG(rawData) {
194	  const heroes = rawData.map(h => ({
195	    name: h.heroName,
196	    headIcon: gameConfig.headIconPath ? ("曙光英雄/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
197	    appearanceRank: parseInt(h.appearanceRank),
198	    combatPower: parseFloat(h.combatPower),
199	    winRate: parseFloat(String(h.winRate).replace("%", "")) / 100,
200	    lane: null
201	  }));
202	
203	  const N = heroes.length;
204	  const weights = gameConfig.algorithm.weights;
205	
206	  // 出场分：rank 越小越好，转换为 1 → 1.0, N → 0.0
207	  const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
208	
209	  // 战力分 min-max 归一化
210	  const combatVals = heroes.map(h => h.combatPower);
211	  const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
212	  const combatRange = combatMax - combatMin || 1;
213	  const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
214	
215	  // 胜率 min-max 归一化
216	  const wrVals = heroes.map(h => h.winRate);
217	  const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
218	  const wrRange = wrMax - wrMin || 1;
219	  const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
220	
221	  // 加权和
222	  heroes.forEach((h, i) => {
223	    h.raw_weighted = weights.appearance * appearanceScores[i]
224	                   + weights.combat * combatScores[i]
225	                   + weights.winrate * wrScores[i];
226	  });
227	
228	  // 最终 min-max 归一化 → 0~100
229	  const rawVals = heroes.map(h => h.raw_weighted);
230	  const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
231	  const rawRange = rawMax - rawMin || 1;
232	  heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });
233	
234	  // 分配梯度
235	  const sorted = [...heroes].sort((a, b) => b.score - a.score);
236	  const thresholds = getTierThresholds();
237	  sorted.forEach((h, i) => {
238	    const pct = 1 - i / N;
239	    let tier = "T4";
240	    for (const t of thresholds) {
241	      if (pct >= t.pct) { tier = t.tier; break; }
242	    }
243	    h.tier = tier;
244	    h.rank = i + 1;
245	  });
246	
247	  return { heroes, sorted };
248	}
