253	async function loadGameData() {
254	  const base = gameConfig.gameId === "lolm" ? "lolm" : "曙光英雄";
255	
256	  if (gameConfig.hasLanes) {
257	    // LOLM: 加载所有分路 JSON
258	    const results = await Promise.all(
259	      gameConfig.lanes.map(async lane => {
260	        const resp = await fetch(base + "/" + lane.dataFile);
261	        if (!resp.ok) throw new Error(`加载 ${lane.dataFile} 失败: ${resp.status}`);
262	        return [lane.name, await resp.json()];
263	      })
264	    );
265	    const rawData = Object.fromEntries(results);
266	    const data = computeLOLM(rawData);
267	
268	    // 转换为标准格式
269	    gameData = {
270	      hasLanes: true,
271	      lanes: {},
272	      allHeroes: data.allHeroes,
273	      globalZ: data.globalZ,
274	      globalSimple: data.globalSimple
275	    };
276	    for (const [name, heroes] of Object.entries(data.lanes)) {
277	      gameData.lanes[name] = heroes;
278	    }
279	  } else {
280	    // 无分路模式：支持多日期或单文件
281	    let dataFile;
282	    if (gameConfig.hasDates && gameConfig.dates && gameConfig.dates.length > 0) {
283	      const dateEntry = gameConfig.dates.find(d => d.date === currentDate) || gameConfig.dates[0];
284	      dataFile = dateEntry.file;
285	      if (!currentDate) currentDate = dateEntry.date;
286	    } else {
287	      dataFile = gameConfig.dataFile;
288	    }
289	    const resp = await fetch(base + "/" + dataFile);
290	    if (!resp.ok) throw new Error(`加载数据失败: ${resp.status}`);
291	    const rawData = await resp.json();
292	    const data = computeSG(rawData);
293	    gameData = {
294	      hasLanes: false,
295	      heroes: data.heroes,
296	      sorted: data.sorted
297	    };
298	
299	    // 如果有历史数据，加载上一期数据用于梯度变化对比
300	    if (gameConfig.hasDates && gameConfig.dates && gameConfig.dates.length >= 2) {
301	      const sortedDates = gameConfig.dates.map(d => d.date).sort();
302	      const curIdx = sortedDates.indexOf(currentDate);
303	      if (curIdx > 0) {
304	        const prevDate = sortedDates[curIdx - 1];
305	        const prevEntry = gameConfig.dates.find(d => d.date === prevDate);
306	        if (prevEntry) {
307	          try {
308	            const prevResp = await fetch(base + "/" + prevEntry.file);
309	            if (prevResp.ok) {
310	              const prevRaw = await prevResp.json();
311	              const prevResult = computeSG(prevRaw);
312	              const prevMap = new Map(prevResult.heroes.map(h => [h.name, h]));
313	              data.heroes.forEach(h => {
314	                const prev = prevMap.get(h.name);
315	                if (prev) {
316	                  h.prevTier = prev.tier;
317	                  h.prevScore = prev.score;
318	                  h.prevRank = prev.rank;
319	                }
320	              });
321	            }
322	          } catch (e) { /* 静默失败，不影响当前数据展示 */ }
323	        }
324	      }
325	    }
326	  }
327	}
