750	function sortTable(th, colIdx) {
751	  const table = th.closest("table");
752	  const tbody = table.querySelector("tbody");
753	  const rows = Array.from(tbody.querySelectorAll("tr"));
754	  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
755	
756	  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
757	  th.classList.add("sorted");
758	  if (isDesc) th.classList.add("desc");
759	
760	  // Determine which heroes list is active
761	  let heroes;
762	  if (gameData.hasLanes) {
763	    if (currentView === "global") {
764	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
765	    } else {
766	      heroes = gameData.lanes[currentLane] || [];
767	    }
768	  } else {
769	    heroes = gameData.heroes;
770	  }
771	
772	  // Build column definitions
773	  let cols;
774	  if (gameData.hasLanes && currentView === "global") {
775	    cols = gameConfig.globalColumns;
776	  } else {
777	    cols = gameConfig.columns;
778	  }
779	
780	  // Handle lane-specific rank column
781	  const col = (colIdx < cols.length) ? cols[colIdx] : { field: "globalRank", type: "rank" };
782	
783	  // 动态找到英雄名列的索引（而非硬编码 cells[1]）
784	  const nameColIdx = cols.findIndex(c => c.field === "name");
785	  rows.sort((a, b) => {
786	    const heroA = heroes.find(h => h.name === a.cells[nameColIdx]?.textContent?.trim());
787	    const heroB = heroes.find(h => h.name === b.cells[nameColIdx]?.textContent?.trim());
788	    const va = heroA ? (col.field === "laneRank" ? heroA.laneRank : heroA[col.field]) : 0;
789	    const vb = heroB ? (col.field === "laneRank" ? heroB.laneRank : heroB[col.field]) : 0;
790	
791	    if (col.type === "tier") {
792	      const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
793	      const ia = order.indexOf(va), ib = order.indexOf(vb);
794	      return isDesc ? ib - ia : ia - ib;
795	    }
796	    const na = parseFloat(va), nb = parseFloat(vb);
797	    if (!isNaN(na) && !isNaN(nb)) {
798	      return isDesc ? nb - na : na - nb;
799	    }
800	    const sa = String(va != null ? va : ""), sb = String(vb != null ? vb : "");
801	    return isDesc ? sb.localeCompare(sa) : sa.localeCompare(sb);
802	  });
803	
804	  rows.forEach(r => tbody.appendChild(r));
805	}
